// Turns Claude's answer into clean fields for the sheet and the email.
let raw = String($input.first().json.text || '').trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
let a;
try { a = JSON.parse(raw); } catch (e) { a = { summary: raw, temperature: '', stage: '', objections: '', next_step: 'Review the call manually, the AI answer could not be read.', follow_up: '', text_to_send: '' }; }
const lead = $('Upload a call').first().json['Lead name'];
const today = new Date().toLocaleDateString('en-US', { timeZone: 'America/Detroit' });
const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const row = (k, v) => `<tr><td style="padding:6px 12px 6px 0;color:#555;vertical-align:top;white-space:nowrap">${k}</td><td style="padding:6px 0">${esc(v)}</td></tr>`;
const html = `<div style="font-family:Arial,sans-serif;max-width:620px;color:#13233f">
  <h2 style="margin:0 0 10px">Call recap: ${esc(lead)}</h2>
  <table style="border-collapse:collapse;font-size:14px">
  ${row('Temperature', a.temperature)}${row('Stage', a.stage)}${row('Summary', a.summary)}${row('Objections', a.objections)}${row('Next step', a.next_step)}${row('Follow up', a.follow_up)}</table>
  <p style="margin:14px 0 4px;font-weight:700">Text to send</p>
  <div style="padding:10px 12px;background:#f3f5f8;border-radius:6px;font-size:14px">${esc(a.text_to_send)}</div></div>`;
return [{ json: {
  Date: today, Lead: lead, Temperature: a.temperature, Stage: a.stage, Summary: a.summary,
  Objections: a.objections, 'Next Step': a.next_step, 'Follow Up': a.follow_up, 'Text To Send': a.text_to_send,
  subject: `Call recap: ${lead} (${a.temperature || 'review'})`, html
} }];
